import base64
import gzip
import pathlib
import subprocess

PATCH_GZIP_B64 = ""

patch_path = pathlib.Path(".compact_live_tuning.patch")
patch_path.write_bytes(gzip.decompress(base64.b64decode(PATCH_GZIP_B64)))
subprocess.run(["git", "apply", "--check", str(patch_path)], check=True)
subprocess.run(["git", "apply", "--whitespace=fix", str(patch_path)], check=True)
patch_path.unlink()
print("Applied compact live tuning patch")
